/* Le script complet, en cinq morceaux : vérifié dans une session R vierge. */
export const SCRIPT = ["# POL-2000 · séance 8 · Blais (2005) en 2025\n# À refaire chez vous, ligne par ligne, Ctrl + Entrée.\n\nlibrary(dplyr)\nlibrary(haven)\ndf_raw <- readRDS(\"ces2025.rds\")\nnrow(df_raw)\ndf_clean <- data.frame(id = 1:nrow(df_raw))\n\ntable(as_factor(df_raw$cps25_votechoice))\ndf_clean$liberal <- case_when(\n  df_raw$cps25_votechoice == 1 ~ 1,             # le Parti libéral\n  df_raw$cps25_votechoice %in% c(2:6, 8) ~ 0    # un autre parti\n  # 7 (ne sait pas) : aucune ligne, donc NA\n)\ntable(df_clean$liberal, useNA = \"ifany\")","table(df_raw$cps25_religion)\n\ndf_clean$catho <- case_when(\n  df_raw$cps25_religion == 10 ~ 1,   # catholique\n  df_raw$cps25_religion <= 22 ~ 0    # une autre religion, ou aucune\n  # 23 (ne sait pas) : aucune ligne, donc NA\n)\ntable(df_clean$catho, useNA = \"ifany\")","# Les contrôles, tout prêts : copiez-collez ce bloc\ndf_clean$region <- case_when(\n  df_raw$cps25_province == 9 ~ \"Ontario\",\n  df_raw$cps25_province %in% c(4, 5, 7, 10) ~ \"Atlantique\",\n  df_raw$cps25_province %in% c(1, 2, 3, 12) ~ \"Ouest\"\n  # le Québec et les territoires : NA, comme chez Blais\n)\ndf_clean$atlantique <- case_when(\n  df_clean$region == \"Atlantique\" ~ 1,\n  df_clean$region == \"Ontario\" ~ 0\n)\ndf_clean$immigrant <- case_when(\n  df_raw$cps25_bornin_canada == 2 ~ 1,   # né.e hors du Canada\n  df_raw$cps25_bornin_canada == 1 ~ 0\n)\ntable(df_clean$region, useNA = \"ifany\")","df_blais <- filter(df_clean, region %in% c(\"Ontario\", \"Atlantique\"))\nnrow(df_blais)\n\nmodele1 <- lm(liberal ~ catho, data = df_blais)\nmodele2 <- lm(liberal ~ catho + atlantique + immigrant, data = df_blais)\nnobs(modele1)\nnobs(modele2)\n\nlibrary(modelsummary)\noptions(OutDec = \",\")\nnoms <- c(\"(Intercept)\" = \"Constante\", \"catho\" = \"Catholique\",\n  \"atlantique\" = \"Atlantique\", \"immigrant\" = \"Né.e hors du Canada\")\nmodeles <- list(\"Catholique seul\" = modele1, \"Avec contrôles\" = modele2)\nmodelsummary(modeles, stars = TRUE, coef_rename = noms,\n  gof_map = c(\"nobs\", \"r.squared\"))\n\nmodelsummary(modeles, stars = TRUE, coef_rename = noms,\n  gof_map = c(\"nobs\", \"r.squared\"), output = \"blais2025.docx\")","# Si on a le temps : l'Ouest\ndf_ouest <- filter(df_clean, region == \"Ouest\")\nmodele3 <- lm(liberal ~ catho + immigrant, data = df_ouest)\nround(coef(modele3), 3)"];
